// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        vm.assume(ownerCandidate != address(0));
        vm.prank(c.owner());
        c.transferOwnership(ownerCandidate);
        bool ok;
        vm.prank(ownerCandidate);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
